import { computed, ref } from 'vue'
import { defineStore } from 'pinia'

export type AssistantMode = 'knowledge' | 'data' | 'tool' | 'insight'

export interface AssistantMessage {
  id: number
  role: 'user' | 'agent'
  text: string
  time: string
}

export interface AssistantReference {
  title: string
  type: '业务表快照' | '字段说明' | '已审核摘要' | '规范文档'
  scope: string
  version: string
  updatedAt: string
  review: string
}

export interface AssistantTask {
  id: string
  title: string
  mode: AssistantMode
  status: '待复核' | '草稿已生成'
  summary: string
  steps: { title: string; detail: string; status: 'done' | 'active' }[]
  references: string[]
}

const modeTitles: Record<AssistantMode, string> = {
  knowledge: '知识与口径查询',
  data: '结构化数据查询',
  tool: '规划工具任务',
  insight: '规律与版本解读',
}

const defaultReferences: AssistantReference[] = [
  {
    title: '规划 V2 / V3 差异表快照',
    type: '业务表快照',
    scope: '惠州、陆丰油区 / 2026-2028 / 规划版本对比',
    version: '规划 V3 快照 2026-07-13',
    updatedAt: '2026-07-13 10:46',
    review: '已审核摘要关联，正式采用前仍需综合规划室复核',
  },
  {
    title: '产量规划字段与公式说明',
    type: '字段说明',
    scope: '产量剖面汇总、开发井工作量、投产时间',
    version: '模板候选 V1',
    updatedAt: '2026-07-12 16:20',
    review: '字段公式为样例，正式维护责任待确认',
  },
  {
    title: 'QHS 2062 年度产量预测技术规范',
    type: '规范文档',
    scope: '基础、措施、调整井、开发井产量预测',
    version: 'QHS 2062-2022',
    updatedAt: '2026-07-10 09:30',
    review: '已收录，引用范围受当前演示身份限制',
  },
]

export const useWorkbenchStore = defineStore('workbench', () => {
  const assistantOpen = ref(false)
  const assistantMode = ref<AssistantMode>('knowledge')
  const assistantContext = ref('首页总览')
  const assistantPrompt = ref('')
  const messages = ref<AssistantMessage[]>([
    { id: 1, role: 'agent', text: '我会结合当前页面、版本和选中对象整理可复核的建议。', time: '刚刚' },
  ])
  const references = ref<AssistantReference[]>(defaultReferences)
  const tasks = ref<AssistantTask[]>([
    {
      id: 'task-version',
      title: '规划 V2 / V3 差异分析',
      mode: 'insight',
      status: '待复核',
      summary: '定位 2028 年产量增量的主要来源。',
      steps: [
        { title: '读取版本快照', detail: '规划 V2、规划 V3、油气田状态', status: 'done' },
        { title: '汇总差异项', detail: '按油气田、年份和产量构成聚合', status: 'done' },
        { title: '生成复核建议', detail: '投产时间和开发井工作量需确认', status: 'active' },
      ],
      references: defaultReferences.slice(0, 2).map((reference) => reference.title),
    },
  ])
  const activeTaskId = ref('task-version')

  const activeTask = computed(() => tasks.value.find((task) => task.id === activeTaskId.value) ?? tasks.value[0])
  const quickActions = computed(() => {
    if (assistantContext.value.includes('工作簿')) {
      return ['解释当前填写规则', '定位这个异常怎么处理', '生成当前校验摘要']
    }
    if (assistantContext.value.includes('版本')) {
      return ['解释当前版本差异', '生成复核摘要草稿', '列出需要确认的变化项']
    }
    if (assistantContext.value.includes('调整')) {
      return ['解释约束冲突', '整理可调整参数', '生成调整任务草稿']
    }
    return ['解释当前待办', '汇总阻断异常', '生成下一步处理建议']
  })

  function openAssistant(context = '首页总览', mode: AssistantMode = 'knowledge') {
    assistantContext.value = context
    assistantMode.value = mode
    assistantOpen.value = true
  }

  function closeAssistant() {
    assistantOpen.value = false
  }

  function submitAssistant(question = assistantPrompt.value, mode = assistantMode.value) {
    const text = question.trim()
    if (!text) return
    const id = Date.now()
    const title = modeTitles[mode]
    messages.value.push({ id, role: 'user', text, time: '刚刚' })
    messages.value.push({
      id: id + 1,
      role: 'agent',
      text: `已创建“${title}”草稿，已关联${assistantContext.value}的页面上下文与版本快照，需人工复核后使用。`,
      time: '刚刚',
    })
    const task: AssistantTask = {
      id: `task-${id}`,
      title,
      mode,
      status: '待复核',
      summary: text,
      steps: [
        { title: '确认业务上下文', detail: assistantContext.value, status: 'done' },
        { title: mode === 'tool' ? '组织参数与约束' : '整理引用与结果', detail: '保留版本、范围和权限说明', status: 'done' },
        { title: '提交人工复核', detail: '不能直接覆盖正式数据或版本', status: 'active' },
      ],
      references: references.value.slice(0, 2).map((reference) => reference.title),
    }
    tasks.value.unshift(task)
    activeTaskId.value = task.id
    assistantPrompt.value = ''
  }

  return {
    assistantOpen,
    assistantMode,
    assistantContext,
    assistantPrompt,
    messages,
    references,
    tasks,
    activeTaskId,
    activeTask,
    quickActions,
    openAssistant,
    closeAssistant,
    submitAssistant,
  }
})

